export class TurnDeadlineElapsed extends Error {
  constructor() {
    super("request_deadline_elapsed");
  }
}

/** Owns only a wait's timer/listener; the caller still owns the underlying resource. */
export async function awaitBeforeDeadline<T>(
  start: () => Promise<T>,
  deadlineAtMs?: number,
  signal?: AbortSignal,
): Promise<T> {
  if (signal?.aborted) throw signal.reason;
  const controller = new AbortController();
  const abort = () => controller.abort(signal?.reason);
  signal?.addEventListener("abort", abort, { once: true });
  const timer =
    deadlineAtMs === undefined
      ? undefined
      : setTimeout(
          () => controller.abort(new TurnDeadlineElapsed()),
          Math.max(0, deadlineAtMs - Date.now()),
        );
  try {
    const result = await awaitWithAbort(
      Promise.resolve().then(() => {
        controller.signal.throwIfAborted();
        return start();
      }),
      controller.signal,
    );
    controller.signal.throwIfAborted();
    return result;
  } finally {
    if (timer) clearTimeout(timer);
    signal?.removeEventListener("abort", abort);
  }
}

export function awaitWithAbort<T>(task: Promise<T>, signal: AbortSignal): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    const abort = () => reject(signal.reason ?? new Error("acp_operation_aborted"));
    if (signal.aborted) {
      void task.catch(() => undefined);
      abort();
      return;
    }
    signal.addEventListener("abort", abort, { once: true });
    void task.then(resolve, reject).finally(() => signal.removeEventListener("abort", abort));
  });
}

export async function settleWithin(promise: Promise<unknown>, timeoutMs: number): Promise<boolean> {
  let timer: NodeJS.Timeout | undefined;
  try {
    return await Promise.race([
      promise.then(
        () => true,
        () => false,
      ),
      new Promise<boolean>((resolve) => {
        timer = setTimeout(() => resolve(false), timeoutMs);
      }),
    ]);
  } finally {
    if (timer) clearTimeout(timer);
  }
}

import { RoleComponent } from "../../core/domain/components/role";
import { ActionRequest } from "../../core/domain";

export interface RequestSchedulerOptions {
  defaultMaxConcurrentRequests: number;
  scopeResolver?: (request: ActionRequest, role?: RoleComponent) => string | undefined;
  limitResolver?: (request: ActionRequest, role?: RoleComponent) => number | undefined;
  onWait?: (event: {
    request: ActionRequest;
    scope: string;
    queueDepth: number;
    active: number;
    limit: number;
  }) => void;
}
interface Waiter {
  request: ActionRequest;
  signal?: AbortSignal;
  grant: (release: () => void) => void;
  reject: (reason: unknown) => void;
  cleanup: () => void;
}

/** Per-runtime provider semaphore. A lease has one owner; queued work is cancellable. */
export class ScopedRequestScheduler {
  private readonly activeByScope = new Map<string, number>();
  private readonly waitersByScope = new Map<string, Waiter[]>();
  private closed = false;

  constructor(private readonly options: RequestSchedulerOptions) {}

  get snapshot(): { closed: boolean; active: number; queued: number } {
    return {
      closed: this.closed,
      active: [...this.activeByScope.values()].reduce((sum, count) => sum + count, 0),
      queued: [...this.waitersByScope.values()].reduce((sum, queue) => sum + queue.length, 0),
    };
  }

  async acquire(
    request: ActionRequest,
    role?: RoleComponent,
    signal?: AbortSignal,
  ): Promise<() => void> {
    if (this.closed) throw new DOMException("request_scheduler_closed", "AbortError");
    if (signal?.aborted) throw signal.reason;
    if ((request.deadlineAtMs ?? Infinity) <= Date.now())
      throw new Error("request_deadline_elapsed");
    const scope = this.resolveScope(request, role),
      limit = this.resolveLimit(request, role);
    const active = this.activeByScope.get(scope) ?? 0;
    if (!Number.isFinite(limit) || active < limit) {
      this.activeByScope.set(scope, active + 1);
      return this.lease(scope);
    }
    return new Promise<() => void>((resolve, reject) => {
      const queue = this.waitersByScope.get(scope) ?? [];
      this.waitersByScope.set(scope, queue);
      let timer: NodeJS.Timeout | undefined;
      const abort = () =>
        withdraw(signal?.reason ?? new DOMException("request_aborted", "AbortError"));
      const cleanup = () => {
        if (timer) clearTimeout(timer);
        signal?.removeEventListener("abort", abort);
      };
      const waiter: Waiter = { request, signal, grant: resolve, reject, cleanup };
      const withdraw = (reason: unknown) => {
        const current = this.waitersByScope.get(scope);
        const index = current?.indexOf(waiter) ?? -1;
        if (index < 0) return;
        current!.splice(index, 1);
        if (!current!.length) this.waitersByScope.delete(scope);
        cleanup();
        reject(reason);
      };
      queue.push(waiter);
      signal?.addEventListener("abort", abort, { once: true });
      if (request.deadlineAtMs !== undefined)
        timer = setTimeout(
          () => withdraw(new Error("request_deadline_elapsed")),
          Math.max(0, request.deadlineAtMs - Date.now()),
        );
      try {
        this.options.onWait?.({ request, scope, queueDepth: queue.length, active, limit });
      } catch (error) {
        withdraw(error);
      }
      if (signal?.aborted) abort();
    });
  }

  close(reason: unknown = new DOMException("request_scheduler_closed", "AbortError")): void {
    if (this.closed) return;
    this.closed = true;
    for (const queue of this.waitersByScope.values())
      for (const waiter of queue) {
        waiter.cleanup();
        waiter.reject(reason);
      }
    this.waitersByScope.clear();
    // Active slots remain accounted for until their owners release them.
  }

  private lease(scope: string): () => void {
    let released = false;
    return () => {
      if (!released) {
        released = true;
        this.release(scope);
      }
    };
  }

  private resolveScope(request: ActionRequest, role?: RoleComponent): string {
    return this.options.scopeResolver?.(request, role)?.trim() || "default";
  }

  private resolveLimit(request: ActionRequest, role?: RoleComponent): number {
    const resolved = this.options.limitResolver?.(request, role);
    const value =
      typeof resolved === "number" ? resolved : this.options.defaultMaxConcurrentRequests;
    return Number.isFinite(value) ? Math.max(1, Math.floor(value)) : Infinity;
  }

  private release(scope: string): void {
    const queue = this.waitersByScope.get(scope);
    while (queue?.length) {
      const next = queue.shift()!;
      next.cleanup();
      if (next.signal?.aborted || (next.request.deadlineAtMs ?? Infinity) <= Date.now()) {
        next.reject(
          next.signal?.aborted ? next.signal.reason : new Error("request_deadline_elapsed"),
        );
        continue;
      }
      if (!queue.length) this.waitersByScope.delete(scope);
      next.grant(this.lease(scope));
      return;
    }
    this.waitersByScope.delete(scope);
    const active = this.activeByScope.get(scope) ?? 0;
    if (active <= 1) this.activeByScope.delete(scope);
    else this.activeByScope.set(scope, active - 1);
  }
}

import { AcpSession } from "./session";
import { awaitBeforeDeadline } from "../../runtime/turn_deadline";

export const ACP_CLOSE_TIMEOUT_MS = 6_000;
export class AcpInitializationCleanupError extends AggregateError {
  constructor(primary: unknown, cleanup: unknown) {
    super([primary, cleanup], "acp_initialization_cleanup_failed");
  }
}

/** A failed graceful close still forces reclamation and preserves every failure. */
export async function closeAcpSession(
  session: AcpSession,
  force = false,
  timeoutMs = ACP_CLOSE_TIMEOUT_MS,
): Promise<void> {
  const attempt = (forced: boolean) =>
    awaitBeforeDeadline(() => session.close({ force: forced }), Date.now() + timeoutMs);
  try {
    await attempt(force);
  } catch (error) {
    if (force) throw error;
    try {
      await attempt(true);
    } catch (forcedError) {
      if (forcedError === error) throw error;
      throw new AggregateError([error, forcedError], "acp_session_close_failed");
    }
    throw error;
  }
}

/**
 * 管理按玩家复用的 ACP 会话、在途创建和迟到回收，拥有创建中止控制器与关闭任务账本。
 * 输入为玩家、绝对期限及会话工厂；输出为复用或新建会话，关闭时汇总已记录的清理错误。
 * 不变量：会话只回收一次；丢弃先撤销复用入口，关闭后不再创建，超时后迟到的实例仍进入回收。
 * 协议与进程关闭由 session_lifecycle 执行，本池不负责游戏行动授权。
 */
import {
  AcpSession,
  AcpSessionCreateInput,
  AcpSessionFactory,
} from "../../integrations/acp/session";
import {
  ACP_CLOSE_TIMEOUT_MS,
  AcpInitializationCleanupError,
  closeAcpSession,
} from "../../integrations/acp/session_lifecycle";
import { awaitBeforeDeadline, awaitWithAbort } from "../../runtime/turn_deadline";

// promise 是调用方受取消约束的等待；created 保留真实创建结果，供超时后的迟到回收使用。
interface SessionEntry {
  promise: Promise<AcpSession>;
  created: Promise<AcpSession>;
  controller: AbortController;
  session?: AcpSession;
}

/** 同一池拥有所有会话条目及清理账本；玩家丢弃回调只通知上层撤掉相关会话状态。 */
export class AcpSessionPool {
  private readonly entries = new Map<number, SessionEntry>();
  private readonly creations = new Set<Promise<AcpSession>>();
  private readonly retiring = new Set<Promise<void>>();
  // 按会话对象去重关闭；重复丢弃或迟到回调复用首次清理任务及其关闭方式。
  private readonly retired = new WeakMap<AcpSession, Promise<void>>();
  private readonly failures: unknown[] = [];
  private readonly discardedByActor = new Map<number, Promise<void>>();
  private closed = false;
  private unreclaimed = false;

  constructor(
    private readonly onDiscard: (actorId: number) => void,
    private readonly cleanupTimeoutMs = ACP_CLOSE_TIMEOUT_MS,
  ) {}
  get isClosed(): boolean {
    return this.closed;
  }
  get hasUnreclaimedResources(): boolean {
    return this.unreclaimed;
  }
  get snapshot() {
    return {
      closed: this.closed,
      sessions: this.entries.size,
      creating: this.creations.size,
      retiring: this.retiring.size,
    };
  }
  noteCleanupFailure(error: unknown): void {
    this.failures.push(error);
  }

  async getOrCreate(
    actorId: number,
    deadlineAtMs: number,
    prepare: () => { factory: AcpSessionFactory; input: AcpSessionCreateInput },
  ): Promise<AcpSession> {
    if (this.closed) throw new Error("acp_provider_closed");
    if (deadlineAtMs <= Date.now()) throw new Error("acp_deadline_elapsed");
    const existing = this.entries.get(actorId);
    if (existing) return existing.promise;
    // prepare 可执行上层代码，返回后再次检查关闭，避免同步回调在准备期间关闭池。
    const { factory, input } = prepare();
    if (this.closed) throw new Error("acp_provider_closed");
    const controller = new AbortController();
    const timer = setTimeout(
      () => controller.abort(new Error("acp_initialize_timeout")),
      Math.max(0, deadlineAtMs - Date.now()),
    );
    const created = Promise.resolve().then(() => {
      controller.signal.throwIfAborted();
      return factory.createSession({ ...input, actorId, deadlineAtMs, signal: controller.signal });
    });
    this.creations.add(created);
    const entry: SessionEntry = {
      promise: awaitWithAbort(created, controller.signal),
      created,
      controller,
    };
    this.entries.set(actorId, entry);
    void created.then(
      (session) => {
        this.creations.delete(created);
        entry.session = session;
        // 已取消、已关闭或条目被替换时，真实创建仍可能成功；迟到实例不可重新加入复用池。
        if (controller.signal.aborted || this.closed || this.entries.get(actorId) !== entry)
          this.retire(session, true);
      },
      (error) => {
        this.creations.delete(created);
        // 调用方超时后仍收集工厂的清理错误；与中止原因不同的迟到错误也保留为未回收证据。
        if (
          error instanceof AcpInitializationCleanupError ||
          (controller.signal.aborted && error !== controller.signal.reason)
        ) {
          this.failures.push(error);
          this.unreclaimed = true;
        }
      },
    );
    try {
      return await entry.promise;
    } catch (error) {
      if (this.entries.get(actorId) === entry) this.discard(actorId);
      throw error;
    } finally {
      clearTimeout(timer);
    }
  }

  discard(actorId: number): Promise<void> {
    const entry = this.entries.get(actorId);
    if (!entry) return this.discardedByActor.get(actorId) ?? Promise.resolve();
    // 先撤掉复用入口再中止创建；后续调用不能取得这个已丢弃的条目。
    this.entries.delete(actorId);
    entry.controller.abort(new Error("acp_session_discarded"));
    if (entry.session) this.retire(entry.session, true);
    try {
      this.onDiscard(actorId);
    } catch (error) {
      this.failures.push(error);
      this.unreclaimed = true;
    }
    // 丢弃等待有独立清理期限；期限结束不抹掉 created，成功的迟到实例仍由上方回调回收。
    const closing = awaitBeforeDeadline(async () => {
      const session = await entry.created.catch(() => null);
      if (session) await this.retire(session, true);
    }, Date.now() + this.cleanupTimeoutMs).catch((error) => {
      this.failures.push(error);
      this.unreclaimed = true;
    });
    this.discardedByActor.set(actorId, closing);
    this.retiring.add(closing);
    void closing.then(() => {
      this.retiring.delete(closing);
      if (this.discardedByActor.get(actorId) === closing) this.discardedByActor.delete(actorId);
    });
    return closing;
  }

  async close(): Promise<void> {
    this.closed = true;
    for (const [actorId, entry] of this.entries) {
      entry.controller.abort(new Error("acp_provider_closed"));
      if (entry.session) this.retire(entry.session, false);
      try {
        this.onDiscard(actorId);
      } catch (error) {
        this.failures.push(error);
      }
    }
    this.entries.clear();
    try {
      await awaitBeforeDeadline(
        () => Promise.allSettled([...this.creations]),
        Date.now() + this.cleanupTimeoutMs,
      );
    } catch (error) {
      this.failures.push(error);
    }
    // 回收过程中可能加入新关闭任务，循环排空后才消费失败账本；不把超时当作资源已关闭。
    while (this.retiring.size) await Promise.all([...this.retiring]);
    const failures = this.failures.splice(0);
    if (failures.length) throw new AggregateError(failures, "acp_pool_close_failed");
  }

  private retire(session: AcpSession, force: boolean): Promise<void> {
    const existing = this.retired.get(session);
    if (existing) return existing;
    const closing = closeAcpSession(session, force, this.cleanupTimeoutMs).catch((error) => {
      this.failures.push(error);
      this.unreclaimed = true;
    });
    this.retired.set(session, closing);
    this.retiring.add(closing);
    void closing.then(() => this.retiring.delete(closing));
    return closing;
  }
}

/**
 * 负责编排单个原生 SDK 回合；输入为原引擎请求、提示会话与模型客户端，输出为候选工具、重试／回退和玩家记录。
 * 本 owner 持有控制器、截止计时器与待结束任务；期限派生与请求原体由各机制保持原权限检查。
 * 取消／关闭仅收走本 provider 资源，不代替规则预检或领域 commit，不扩大 fallback 的原预算。
 */
import { inheritRequestAlias } from "../../../core/domain/request_delivery";
import { text } from "@ai-werewolf-arena/game-text";
import type { ErrorDiagnostic } from "@ai-werewolf-arena/replay-contract";
import { describeError, formatErrorDiagnostic } from "../../../utils/error_diagnostic";
import { COMPONENT } from "../../../core/domain/components/names";
import { RoleComponent } from "../../../core/domain/components/role";
import { ActionRequest, ToolCall } from "../../../core/domain";
import { World } from "../../../core/domain/world";
import {
  FallbackActionPolicy,
  FallbackDeadlineElapsed,
  FallbackReason,
} from "./fallback_action_policy";
import { LlmObserver } from "../player/player_observer";
import { BuiltPlayerPrompt, PlayerRoundOutcome, PlayerRetryTraceEntry } from "../player/contracts";
import { ChatMessage, ChatModelClient } from "../../integrations/llm/transport";
import { PlayerPromptSession } from "./player_prompt_session";
import { PlayerRoundRecorder } from "../../../app/player-round-recorder";
import { buildConstraintRetryPrompt } from "../player/prompt_templates";
import { ScopedRequestScheduler } from "../../runtime/request_scheduler";
import { SdkGameToolLoop } from "./sdk_game_tool_loop";
import { allowsActionFallback, resolveTurnConstraints } from "../../../game/gateway/turn-constraints";

interface LlmTurnOrchestratorOptions {
  world: World;
  defaultClient: ChatModelClient;
  clientResolver?: (request: ActionRequest, role?: RoleComponent) => ChatModelClient;
  timeoutMs: number;
  promptSession: PlayerPromptSession;
  scheduler: ScopedRequestScheduler;
  sdkToolLoop: SdkGameToolLoop;
  fallbackPolicy: FallbackActionPolicy;
  recorder: PlayerRoundRecorder;
  observer: LlmObserver;
}

interface NativeAttempt {
  action: ToolCall | null;
  failed: boolean;
  deadlineExceeded?: boolean;
  diagnostic?: ErrorDiagnostic;
  assistantText?: string;
  refusalReason?: string;
}

/** 以原尝试顺序编排原生工具回合，已付／已记录前缀不由本服务回滚。 */
export class LlmTurnOrchestrator {
  constructor(private readonly options: LlmTurnOrchestratorOptions) {}

  private readonly controllers = new Set<AbortController>();
  private readonly pending = new Set<Promise<ToolCall | null>>();
  private readonly closeController = new AbortController();
  private closed = false;

  get runtimeState() {
    return {
      closed: this.closed,
      turns: this.pending.size,
      scheduler: this.options.scheduler.snapshot,
    };
  }

  run(request: ActionRequest): Promise<ToolCall | null> {
    if (this.closed) return Promise.reject(new DOMException("llm_provider_closed", "AbortError"));
    const startedAt = Date.now();
    const bounded = {
      ...request,
      deadlineAtMs: Math.min(request.deadlineAtMs ?? Infinity, startedAt + this.options.timeoutMs),
    };
    inheritRequestAlias(request, bounded);
    const controller = new AbortController();
    this.controllers.add(controller);
    const timer = setTimeout(
      () => controller.abort(new Error("request_deadline_elapsed")),
      Math.max(0, bounded.deadlineAtMs - Date.now()),
    );
    let resolve!: (action: ToolCall | null) => void, reject!: (error: unknown) => void;
    const task = new Promise<ToolCall | null>((done, fail) => {
      resolve = done;
      reject = fail;
    });
    this.pending.add(task);
    void this.runTurn(bounded, controller.signal, startedAt).then(resolve, reject);
    const cleanup = () => {
      clearTimeout(timer);
      this.controllers.delete(controller);
      this.pending.delete(task);
    };
    return task.then(
      (action) => {
        cleanup();
        if (this.closed) return this.closedResult(request);
        if (
          bounded.context.action_failure_policy === "error" &&
          (controller.signal.aborted || bounded.deadlineAtMs <= Date.now())
        )
          throw new Error("action_turn_failed");
        return action;
      },
      (error) => {
        cleanup();
        throw error;
      },
    );
  }

  async close(): Promise<void> {
    this.closed = true;
    this.closeController.abort(new DOMException("llm_provider_closed", "AbortError"));
    this.options.scheduler.close(this.closeController.signal.reason);
    for (const controller of this.controllers) controller.abort(this.closeController.signal.reason);
    const settled = await Promise.allSettled([...this.pending]);
    const failures = settled.flatMap((result) =>
      result.status === "rejected" && result.reason !== this.closeController.signal.reason
        ? [result.reason]
        : [],
    );
    if (failures.length) throw new AggregateError(failures, "llm_turns_failed_during_close");
  }

  private async runTurn(
    request: ActionRequest,
    signal: AbortSignal,
    startedAt: number,
  ): Promise<ToolCall | null> {
    const role = this.options.world.getComponent(request.actorId, COMPONENT.Role);
    const client = this.options.clientResolver?.(request, role) ?? this.options.defaultClient;
    const prompt = this.options.promptSession.build(request);
    this.options.observer.trace(
      `context_window player=${request.actorId} phase=${request.phase} start=${prompt.contextWindowStart} end=${prompt.contextWindowEnd} total=${prompt.contextWindowTotal}`,
    );
    let release: (() => void) | undefined;
    try {
      release = await this.options.scheduler.acquire(request, role, signal);
      if (this.closed) return this.closedResult(request);
      if (signal.aborted || this.effectiveTimeout(request.deadlineAtMs) <= 0) {
        return this.finishWithFallback(request, prompt, "deadline_skip");
      }
      this.options.observer.trace(
        `request_start player=${request.actorId} phase=${request.phase} tools=${request.allowedTools.join(",")} timeout_ms=${this.effectiveTimeout(request.deadlineAtMs)}`,
      );
      this.options.observer.prompt(prompt.messages, request);
      const action = await this.runNative(client, request, prompt, startedAt, signal);
      if (
        !this.closed &&
        request.context.action_failure_policy === "error" &&
        (signal.aborted || this.effectiveTimeout(request.deadlineAtMs) <= 0)
      ) {
        return this.finishWithFallback(request, prompt, "deadline_skip", {
          retryTrace: [
            {
              attempt: 0,
              status: "request_error",
              reason: "request_timeout",
              diagnostic: { code: "request_timeout" },
            },
          ],
        });
      }
      return this.closed ? this.closedResult(request) : action;
    } catch (error) {
      const diagnostic = describeError(error);
      if (this.closed && (error === this.closeController.signal.reason || error === signal.reason))
        return this.closedResult(request);
      // 原生传输失败已由 runNative 处理；回退或记录失败只传播一次，不能再次调用回退。
      if (release) throw error;
      this.options.observer.trace(
        `${diagnostic.code === "request_timeout" ? "request_timeout" : "request_transport_fail"} player=${request.actorId} phase=${request.phase} elapsed_ms=${Date.now() - startedAt} err=${formatErrorDiagnostic(error, this.options.observer.locale)}`,
      );
      return this.finishWithFallback(
        request,
        prompt,
        diagnostic.code === "request_timeout" ? "deadline_skip" : "runtime_error",
      );
    } finally {
      release?.();
    }
  }

  private async runNative(
    client: ChatModelClient,
    request: ActionRequest,
    prompt: BuiltPlayerPrompt,
    startedAt: number,
    signal: AbortSignal,
  ): Promise<ToolCall | null> {
    const retryTrace: PlayerRetryTraceEntry[] = [];
    const attempt = async (messages: ChatMessage[]): Promise<NativeAttempt> => {
      const timeoutMs = this.effectiveTimeout(request.deadlineAtMs);
      if (signal.aborted || timeoutMs <= 0) {
        return {
          action: null,
          failed: false,
          deadlineExceeded: true,
          diagnostic: { code: "request_timeout" },
        };
      }
      try {
        const result = await this.options.sdkToolLoop.run(
          client,
          request,
          messages,
          timeoutMs,
          prompt.turnId,
          signal,
        );
        if (
          request.context.action_failure_policy === "error" &&
          (signal.aborted || this.effectiveTimeout(request.deadlineAtMs) <= 0)
        ) {
          return {
            action: null,
            failed: false,
            deadlineExceeded: true,
            diagnostic: { code: "request_timeout" },
          };
        }
        return {
          action: result.action,
          failed: result.failureCode !== undefined,
          refusalReason: result.failureCode,
          assistantText: result.thinkingText,
        };
      } catch (error) {
        const diagnostic = describeError(error);
        this.options.observer.trace(
          `request_sdk_attempt_fail player=${request.actorId} phase=${request.phase} err=${formatErrorDiagnostic(error, this.options.observer.locale)}`,
        );
        return { action: null, failed: true, diagnostic };
      }
    };

    const first = await attempt(prompt.messages);
    if (this.closed) return this.closedResult(request);
    if (first.deadlineExceeded)
      return this.finishWithFallback(request, prompt, "deadline_skip", {
        ...(request.context.action_failure_policy === "error"
          ? {
              retryTrace: [
                {
                  attempt: 0,
                  status: "request_error" as const,
                  reason: "request_timeout",
                  diagnostic: first.diagnostic ?? { code: "request_timeout" as const },
                },
              ],
            }
          : {}),
      });
    if (first.failed) {
      retryTrace.push({
        attempt: 0,
        status: first.refusalReason ? "no_valid_action" : "request_error",
        reason: first.refusalReason ?? first.diagnostic?.code,
        diagnostic: first.diagnostic,
        assistantText: first.assistantText,
      });
      return this.finishWithFallback(
        request,
        prompt,
        first.refusalReason ? "model_declined_required_action" : "runtime_error",
        {
          thinkingText: first.assistantText,
          retryTrace,
        },
      );
    }
    if (first.action)
      return this.finishWithAction(request, prompt, first.action, startedAt, {
        thinkingText: first.assistantText,
      });
    if (!this.requiresAction(request)) {
      this.options.observer.trace(
        `request_none player=${request.actorId} phase=${request.phase} elapsed_ms=${Date.now() - startedAt}`,
      );
      this.options.recorder.record(request, prompt, {
        actionMode: "none",
        toolCalls: [],
        thinkingText: first.assistantText,
      });
      return null;
    }

    retryTrace.push({
      attempt: 0,
      status: "no_valid_action",
      reason: "turn_constraints_no_valid_action",
      assistantText: first.assistantText,
    });
    let messages = [...prompt.messages];
    for (let attemptNumber = 1; attemptNumber <= 3; attemptNumber++) {
      const retryPrompt = buildConstraintRetryPrompt(attemptNumber, 3, this.options.world.locale);
      messages = [...messages, { role: "user", content: retryPrompt }];
      console.log(
        `[LLM_RETRY] player=${request.actorId} phase=${request.phase} attempt=${attemptNumber}/3 reason=turn_constraints_no_valid_action · ${text(this.options.observer.locale, "runtime.retry")}`,
      );
      const trace: PlayerRetryTraceEntry = {
        attempt: attemptNumber,
        status: "no_valid_action",
        reason: "turn_constraints_no_valid_action",
        retryPrompt,
      };
      retryTrace.push(trace);
      this.options.observer.prompt(messages, request);
      const result = await attempt(messages);
      if (this.closed) return this.closedResult(request);
      trace.assistantText = result.assistantText;
      if (result.deadlineExceeded) {
        trace.reason = result.diagnostic?.code;
        trace.diagnostic = result.diagnostic;
        return this.finishWithFallback(request, prompt, "deadline_skip", {
          thinkingText: result.assistantText,
          retryTrace,
        });
      }
      if (result.failed) {
        trace.status = result.refusalReason ? "no_valid_action" : "request_error";
        trace.reason = result.refusalReason ?? result.diagnostic?.code;
        trace.diagnostic = result.diagnostic;
        return this.finishWithFallback(
          request,
          prompt,
          result.refusalReason ? "model_declined_required_action" : "runtime_error",
          {
            thinkingText: result.assistantText,
            retryTrace,
          },
        );
      }
      if (result.action) {
        return this.finishWithAction(request, prompt, result.action, startedAt, {
          thinkingText: result.assistantText,
          retryTrace,
          retryAttempt: attemptNumber,
        });
      }
    }
    return this.finishWithFallback(request, prompt, "model_declined_required_action", {
      thinkingText: retryTrace.at(-1)?.assistantText,
      retryTrace,
    });
  }

  private async finishWithAction(
    request: ActionRequest,
    prompt: BuiltPlayerPrompt,
    action: ToolCall,
    startedAt: number,
    extras: {
      thinkingText?: string;
      retryTrace?: PlayerRetryTraceEntry[];
      retryAttempt?: number;
    } = {},
  ): Promise<ToolCall | null> {
    if (this.closed) return this.closedResult(request);
    this.options.observer.trace(
      `${extras.retryAttempt ? "request_ok_retry" : "request_ok"} player=${request.actorId} phase=${request.phase}${extras.retryAttempt ? ` attempt=${extras.retryAttempt}/3` : ""} action=${action.name} args=${JSON.stringify((action as any).args ?? {})} elapsed_ms=${Date.now() - startedAt}`,
    );
    if (this.closed) return this.closedResult(request);
    this.options.recorder.record(request, prompt, {
      actionMode: "tool_call",
      toolCalls: this.toToolCalls(action),
      finalAction: action,
      thinkingText: extras.thinkingText,
      ...(extras.retryTrace?.length ? { retryTrace: [...extras.retryTrace] } : {}),
    });
    return this.closed ? this.closedResult(request) : action;
  }

  private async finishWithFallback(
    request: ActionRequest,
    prompt: BuiltPlayerPrompt,
    reason: FallbackReason,
    extras: Pick<PlayerRoundOutcome, "thinkingText" | "retryTrace"> = {},
  ): Promise<ToolCall | null> {
    if (this.closed) return this.closedResult(request);
    let action: ToolCall | null;
    try {
      action = await this.options.fallbackPolicy.resolve(
        request,
        reason,
        this.closeController.signal,
      );
    } catch (error) {
      if (error === this.closeController.signal.reason) return this.closedResult(request);
      if (!(error instanceof FallbackDeadlineElapsed)) throw error;
      action = null;
      reason = "deadline_skip";
    }
    if (this.closed) return this.closedResult(request);
    this.options.recorder.record(request, prompt, {
      actionMode: action ? "tool_call" : "none",
      toolCalls: this.toToolCalls(action),
      finalAction: action,
      ...extras,
      fallback: {
        used: allowsActionFallback(request),
        reason,
        ...(action ? { action: { name: action.name, args: (action as any).args ?? {} } } : {}),
      },
    });
    if (!this.closed && request.context.action_failure_policy === "error" && !action)
      throw new Error("action_turn_failed");
    return this.closed ? this.closedResult(request) : action;
  }

  private toToolCalls(action?: ToolCall | null) {
    return action
      ? [
          {
            name: action.name,
            args: ((action as any).args ?? {}) as Record<string, unknown>,
            accepted: true,
          },
        ]
      : [];
  }

  private requiresAction(request: ActionRequest): boolean {
    return resolveTurnConstraints(request).minValidActions > 0;
  }
  private closedResult(request: ActionRequest): null {
    if (request.context.action_failure_policy === "error") throw this.closeController.signal.reason;
    return null;
  }

  private effectiveTimeout(deadlineAtMs?: number): number {
    if (!deadlineAtMs) return this.options.timeoutMs;
    const remaining = deadlineAtMs - Date.now();
    return remaining <= 0 ? 0 : Math.max(1, Math.min(this.options.timeoutMs, remaining));
  }
}
